package net.civeira.phylax.common.infrastructure.audit;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.sql.Connection;
import java.sql.DatabaseMetaData;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;
import java.util.Map;

import javax.sql.DataSource;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.mockito.ArgumentCaptor;

import com.fasterxml.jackson.databind.ObjectMapper;

@DisplayName("AuditReadService")
class AuditReadServiceUnitTest {
  private DataSource dataSource;
  private Connection conn;
  private DatabaseMetaData meta;
  private PreparedStatement ps;
  private ResultSet rs;
  private AuditReadService service;

  @BeforeEach
  void setUp() throws SQLException {
    dataSource = mock(DataSource.class);
    conn = mock(Connection.class);
    meta = mock(DatabaseMetaData.class);
    ps = mock(PreparedStatement.class);
    rs = mock(ResultSet.class);
    when(dataSource.getConnection()).thenReturn(conn);
    when(conn.getMetaData()).thenReturn(meta);
    when(meta.getDriverName()).thenReturn("H2 JDBC Driver");
    when(conn.prepareStatement(anyString())).thenReturn(ps);
    when(ps.executeQuery()).thenReturn(rs);
    service = new AuditReadService(dataSource, new ObjectMapper());
  }

  private String sql() throws SQLException {
    ArgumentCaptor<String> sql = ArgumentCaptor.forClass(String.class);
    verify(conn).prepareStatement(sql.capture());
    return sql.getValue();
  }

  @ParameterizedTest(name = "{0}")
  @CsvSource({"PostgreSQL JDBC Driver, LIMIT ? OFFSET ?", "Oracle JDBC driver, LIMIT ? OFFSET ?",
      "MariaDB Connector/J, 'LIMIT ?, ?'", "MySQL Connector/J, 'LIMIT ?, ?'",
      "Microsoft JDBC Driver for SQLServer, LIMIT ? OFFSET ?", "H2 JDBC Driver, LIMIT ? OFFSET ?"})
  @DisplayName("Should page the query with the syntax of the database")
  void shouldPageByDriver(String driver, String paging) throws SQLException {
    when(meta.getDriverName()).thenReturn(driver);

    service.findByFilters("_audit", "role", AuditQueryFilter.builder().build(), null, 10, 20);

    assertTrue(sql().endsWith("ORDER BY timestamp DESC " + paging), sql());
    verify(ps).setObject(1, 10);
    verify(ps).setObject(2, 20);
  }

  @Test
  @DisplayName("Should filter by tenant and read every column of the events")
  void shouldReadEvents() throws SQLException {
    // Arrange — one stored event with valid and corrupted json columns
    when(rs.next()).thenReturn(true, false);
    when(rs.getString("operation")).thenReturn("update");
    when(rs.getString("entity_id")).thenReturn("e-1");
    when(rs.getString("old_values")).thenReturn("{\"name\":\"a\"}");
    when(rs.getString("new_values")).thenReturn("{not json");
    when(rs.getString("claims")).thenReturn("{}");
    when(rs.getTimestamp("timestamp")).thenReturn(Timestamp.from(Instant.EPOCH));

    // Act — query the events of a tenant
    List<AuditEvent> events = service.findByFilters("_audit", "role",
        AuditQueryFilter.builder().performedBy("u").build(), "acme", 50, 0);

    // Assert — the tenant is a parameter and corrupted json becomes an empty map
    assertTrue(sql().contains("AND tenant = ? "));
    verify(ps).setObject(1, "u");
    verify(ps).setObject(2, "acme");
    assertEquals(1, events.size());
    assertEquals("update", events.get(0).getOperation());
    assertEquals(Map.of("name", "a"), events.get(0).getOldValue());
    assertEquals(Map.of(), events.get(0).getNewValue());
    assertEquals(Instant.EPOCH, events.get(0).getTimestamp().toInstant());
  }

  @Test
  @DisplayName("Should wrap SQL errors")
  void shouldWrapSqlErrors() throws SQLException {
    when(dataSource.getConnection()).thenThrow(new SQLException("down"));

    assertThrows(RuntimeException.class, () -> service.findByFilters("_audit", "role",
        AuditQueryFilter.builder().build(), null, 10, 0));
  }

  @Test
  @DisplayName("Should return an empty map when a json column cannot be read")
  void shouldTolerateUnreadableJsonColumn() throws SQLException {
    when(rs.next()).thenReturn(true, false);
    when(rs.getString("old_values")).thenThrow(new SQLException("bad column"));
    when(rs.getString("new_values")).thenReturn("{}");
    when(rs.getString("claims")).thenReturn("{}");
    when(rs.getTimestamp("timestamp")).thenReturn(Timestamp.from(Instant.EPOCH));

    List<AuditEvent> events =
        service.findByFilters("_audit", "role", AuditQueryFilter.builder().build(), null, 10, 0);

    assertEquals(Map.of(), events.get(0).getOldValue());
  }
}
